// Проверка прототипа во встроенном режиме data:, где нет localStorage и переходов по адресу.
// Обычный режим проверяет test_prototype.js. Здесь нажатия идут так же, как у человека: через кнопки и ссылки.
const path = require("node:path"), fs = require("node:fs");
const { launch, sleep } = require("./cdp");
const html = fs.readFileSync(path.resolve(__dirname, "../../prototype/index.html"), "utf8");
let fails = 0;
const check = (n, ok, x = "") => { console.log(`${ok ? "ok   " : "ОШИБКА"} ${n}${x ? " → " + x : ""}`); if (!ok) fails++; };
(async () => {
  const c = await launch();
  await c.size(1040, 900);
  await c.open("data:text/html;charset=utf-8," + encodeURIComponent(html));
  const text = () => c.ev(`document.getElementById("app").innerText`);
  const click = async (sel) => { await c.ev(`document.querySelector(${JSON.stringify(sel)}).click()`); await sleep(60); };
  const role = async (t) => { await c.ev(`[...document.querySelectorAll("#roles a")].find(a=>a.textContent===${JSON.stringify(t)}).click()`); await sleep(60); };
  const set = (sel, v) => c.ev(`(()=>{const e=document.querySelector(${JSON.stringify(sel)});e.value=${JSON.stringify(v)};e.dispatchEvent(new Event("input",{bubbles:true}))})()`);
  check("режим data: без localStorage", (await c.ev(`location.protocol`)) === "data:");
  await set("#ph", "+998 90 000 00 00"); await set("#pw", "123");
  await click('#f button[type=submit]');
  check("короткий пароль отклонён, телефон не стёрт", (await text()).includes("не меньше 8") && (await c.ev(`document.getElementById("ph").value`)) === "+998 90 000 00 00");
  await set("#pw", "testpass1");
  await click('#f button[type=submit]');
  check("«Продолжить» ведёт на загрузку файла", (await text()).includes("Шаг 2 из 5"));
  await click("#demo"); await click("#next");
  check("переход к параметрам", (await text()).includes("Шаг 3 из 5"));
  await c.ev(`(()=>{const r=document.querySelector('input[name=binding][value=spring]');r.checked=true;r.dispatchEvent(new Event("change",{bubbles:true}))})()`);
  await set("#cp", "3"); await sleep(40);
  check("переплёт считается на каждую копию", (await text()).includes("61 000 сум"), "(24 × 500 + 8000) × 3 + сбор");
  await set("#cp", "1");
  await click("#next");
  check("переход к оплате", (await text()).includes("Шаг 4 из 5"));
  await click("#payb");
  check("заказ оплачен, показан код", (await text()).includes("Шаг 5 из 5"));
  const code = await c.ev(`document.querySelector(".code").textContent`);
  await role("Оператор печати");
  check("роль оператора открывается", (await text()).includes("Очередь заказов") && (await text()).includes("Курсовая.pdf"));
  await role("Администратор точки");
  check("роль администратора открывается", (await text()).includes("Цены точки"));
  await click('.subnav a[href="#/admin/revenue"]');
  check("ссылка «Выручка» работает", (await text()).includes("Выручка точки"));
  await role("Оператор печати");
  await click('.subnav a[href="#/op/issue"]');
  check("ссылка «Выдача по коду» работает", (await text()).includes("Выдача по коду"));
  await role("Клиент");
  check("возврат к клиенту, сессия сохранена", (await text()).includes("Шаг 2 из 5"));
  await click('.subnav a[href="#/orders"]');
  check("в «Моих заказах» есть заказ", (await text()).includes("Заказ №"));
  await click("#reset");
  check("«Сбросить данные» возвращает ко входу", (await text()).includes("Вход или регистрация"));
  check("код выдан", /^\d{4}$/.test(code), code);
  check("ошибок JavaScript нет", c.errors.length === 0, c.errors.map((e) => String(e).slice(0, 120)).join(" | "));
  await c.close();
  console.log(fails ? `Провалов: ${fails}` : "Встроенный режим: все проверки прошли");
  process.exit(fails ? 1 : 0);
})().catch((e) => { console.error(e); process.exit(2); });
